  "subscribe.noPaymentNote": "ఇక్కడ చెల్లింపు తీసుకోబడడం లేదు, ట్రయల్ కూడా ప్రారంభం కాలేదు — వర్క్‌స్పేస్‌ను ఎంచుకోవడం వల్ల సబ్‌స్క్రిప్షన్ దానికి మాత్రమే అనుసంధానించబడుతుంది.",
