  "plans.changePlan": "ప్లాన్‌ను మార్చండి",
  "plans.subscribe": "సబ్‌స్క్రైబ్ చేయండి",
  "plans.featureHeader": "ఫీచర్",
  "plans.perMonthShort": "/నెల",
  "plans.included": "చేర్చబడింది",
  "plans.notIncluded": "చేర్చబడలేదు",
  "plans.mobileIncludedNote": "రెండు వెబ్‌సైట్ ప్లాన్‌లలోనూ మొబైల్ సహాయకుడు చేర్చబడింది, కాబట్టి వెబ్‌సైట్ సబ్‌స్క్రైబర్ నెలవారీ మొబైల్ రుసుమును కూడా ఎప్పుడూ చెల్లించరు.",
  "plans.priceNote": "Essentials నెలకు $14.99, వర్తించే పన్నులతో పాటు, ఏవైనా ఉంటే. Business నెలకు $29.99, వర్తించే పన్నులతో పాటు, ఏవైనా ఉంటే. అవసరమైన ఏదైనా పన్ను ప్రొవైడర్ చెక్అవుట్ సమయంలో నిర్ణయించబడుతుంది మరియు చెల్లింపుకు ముందు తుది మొత్తంలో కనిపించాలి. ఈ పోలిక పేజీ పన్ను కోట్ లేదా చెల్లింపు అధికారం కాదు.",
  "plans.mobilePriceNote": "మొబైల్-మాత్రమే ప్లాన్ దాని ఉద్దేశించిన U.S. మూల ధర వద్ద నెలకు $4.99. App Store లేదా Google Play కొనుగోలుకు ముందు అసలు స్థానిక సబ్‌స్క్రిప్షన్ ధరను మరియు వర్తించే పన్నులను చూపుతుంది. దాని ఉత్పత్తి, సైట్ మరియు సిబ్బంది అనుమతులు వెబ్‌సైట్ శ్రేణుల నుండి వేరుగా, ప్రారంభంలో సెట్ చేయబడతాయి.",
  "plans.planChangeNote": "వెబ్‌సైట్ ప్లాన్ మార్పును బిల్లింగ్ ప్రొవైడర్ నిర్ధారించాలి. మార్పు అధికారికం కావడానికి ముందు కొత్త ధర, అమలు తేదీ మరియు ఏదైనా నిష్పత్తి వివరించబడతాయి. అప్‌గ్రేడ్ రెండవ సబ్‌స్క్రిప్షన్‌ను సృష్టించకూడదు.",
  "plans.providerNote": "ధరలు, ఛార్జీలు మరియు ట్రయల్‌లను మీరు దేని ద్వారా సబ్‌స్క్రైబ్ చేస్తారో ఆ ప్రొవైడర్ నిర్వహిస్తారు — App Store, Google Play, వెబ్‌సైట్ లేదా Shopify — ఈ పేజీ ఎప్పుడూ కాదు.",
