  "upgrade.reviewPeriod": ".",
  "upgrade.upgradeNeverRestartsTrial": "అప్‌గ్రేడ్ చేయడం వల్ల మీ ఉచిత ట్రయల్ ఎప్పుడూ మళ్లీ ప్రారంభం కాదు.",
  "upgrade.trialHistoryNote": "మీరు Essentials కోసం చెల్లిస్తూ Businessకు మారితే, మీరు అదే కస్టమర్ ఖాతాను మరియు ట్రయల్ చరిత్రను ఉంచుకుంటారు. Businessలో అదనపు ఏడు రోజుల ట్రయల్ చేర్చబడలేదు. మీ అసలు ట్రయల్ ఇంకా నడుస్తున్నప్పుడు మీరు అప్‌గ్రేడ్ చేస్తే, దాని అసలు ముగింపు తేదీ రీసెట్ కాదు.",
  "upgrade.providerConfirmNote": "ప్లాన్ మార్పులకు బిల్లింగ్ ప్రొవైడర్ నుండి నిర్ధారణ అవసరం. మీరు మార్పును ఆమోదించే ముందు ఏదైనా ధర వ్యత్యాసం, నిష్పత్తి మరియు అమలు తేదీ తప్పనిసరిగా చూపబడాలి. అప్‌గ్రేడ్ రెండవ ఏకకాల సబ్‌స్క్రిప్షన్‌ను సృష్టించకూడదు.",
  "upgrade.chargedThroughProviderNote": "ప్లాన్ మార్పులకు బిల్లింగ్ ప్రొవైడర్ ద్వారా ఛార్జీ పడుతుంది. మీ ప్రస్తుత ప్లాన్ క్రింద ఉన్న సబ్‌స్క్రిప్షన్‌ను రద్దు చేయండి బటన్‌ను ఉపయోగించి ఈ పేజీ నుండి, లేదా సెట్టింగ్‌ల నుండి మీరు మీ సబ్‌స్క్రిప్షన్‌ను రద్దు చేయవచ్చు. రద్దు చేయడం వల్ల మీ చెల్లించిన కాలం చివరిలో భవిష్యత్ పునరుద్ధరణలు ఆగిపోతాయి; అది మీ ప్రాప్యతను ఒకేసారి ఎప్పుడూ ముగించదు. ఈ ఎంపికలను వీక్షించడం వల్ల ఇప్పటికే ఉన్న ఉచిత వర్క్‌స్పేస్‌లపై ఛార్జీ పడదు.",
