  "billing.cancel.doneWithEnd": "మీకు {endDate} వరకు పూర్తి ప్రాప్యత ఉంటుంది. ఆ తేదీ తర్వాత మీకు {graceDays} రోజుల చదవడానికి-మాత్రమే గ్రేస్ కాలం ఉంటుంది — మీరు ఇంకా లాగిన్ అయి మీ ఉత్పత్తులను చూడవచ్చు, కానీ మీరు ఏదీ జోడించలేరు, సవరించలేరు, తొలగించలేరు, స్కాన్ చేయలేరు, దిగుమతి చేయలేరు, ఎగుమతి చేయలేరు లేదా మార్చలేరు. {gracePart}",
