  "billing.cancel.doneNoEnd": "మీ చెల్లించిన కాలం ముగిసే వరకు మీకు పూర్తి ప్రాప్యత ఉంటుంది. ఆ తర్వాత, 15 రోజుల చదవడానికి-మాత్రమే గ్రేస్ కాలం వర్తిస్తుంది. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "మీరు మీ మొదటి చెల్లించిన ఛార్జీకి 3 రోజులలోపు రద్దు చేశారు, కాబట్టి ఆ మొదటి చెల్లింపు వాపసుకు మీరు అర్హులు కావచ్చు. రద్దు చేయడం వల్ల వాపసు స్వయంగా జారీ కాదు — {contact} ద్వారా దాన్ని అభ్యర్థించండి.",
  "billing.cancel.refundWindowClosed": "రద్దు చేయడం వల్ల దానంతట అదే వాపసు జారీ కాదు. వాపసులు మొదటి విజయవంతమైన చెల్లించిన ఛార్జీకి 3 రోజులలోపు మాత్రమే వర్తిస్తాయి, {contact} ద్వారా అభ్యర్థించాలి.",
  "billing.cancel.notCanceledTitle": "మీ సబ్‌స్క్రిప్షన్ రద్దు చేయబడలేదు.",
