  "billing.cancel.alreadyCanceledTitle": "ఈ సబ్‌స్క్రిప్షన్ ఇప్పటికే రద్దు చేయబడింది.",
  "billing.cancel.alreadyCanceledWithEnd": "అది {date}న ముగుస్తుంది. అప్పటి వరకు మీకు పూర్తి ప్రాప్యత ఉంటుంది. ఆ తేదీ తర్వాత మీ ఉత్పత్తులను చూడడానికి మీకు {graceDays} రోజుల చదవడానికి-మాత్రమే గ్రేస్ కాలం ఉంటుంది. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "అది ప్రస్తుత చెల్లించిన కాలం చివరిలో ముగుస్తుంది. అప్పటి వరకు మీకు పూర్తి ప్రాప్యత ఉంటుంది.",
  "billing.cancel.appStoreNote": "మీరు ఎప్పుడైనా Google Play లేదా Apple App Store ద్వారా సబ్‌స్క్రైబ్ చేస్తే, ఆ స్టోర్ యొక్క సబ్‌స్క్రిప్షన్ సెట్టింగ్‌ల ద్వారా దాన్ని రద్దు చేయాల్సి రావచ్చు. ఈ డైలాగ్ యాప్-స్టోర్ బిల్లింగ్‌ను ఆపలేదు. యాప్‌ను అన్‌ఇన్‌స్టాల్ చేయడం లేదా మీ StockHaven ఖాతాను తొలగించడం వల్ల స్టోర్ సబ్‌స్క్రిప్షన్ రద్దు కాదు.",
