  "billing.cancel.gracePeriodRest": "మీరు ఇంకా లాగిన్ అయి మీ ఉత్పత్తులను చూడవచ్చు, కాబట్టి మీ వద్ద ఏమి ఉందో చూసి రాసుకోవచ్చు. మిగతావన్నీ నిరోధించబడ్డాయి: జోడించడం, సవరించడం, తొలగించడం, స్కాన్ చేయడం, దిగుమతి చేయడం, ఎగుమతి చేయడం లేదా మైగ్రేట్ చేయడం లేదు, సెట్టింగ్‌లు లేవు, సిబ్బంది లేరు.",
