  "exports.title": "ఎగుమతులు మరియు బ్యాకప్‌లు",
  "exports.subtitleStart": "డౌన్‌లోడ్‌లు ఎల్లప్పుడూ దీనికి మాత్రమే పరిమితం చేయబడతాయి",
  "exports.subtitleRest": ". ప్రతి ఫైల్‌పై వ్యాపార పేరు మరియు అది రూపొందించిన తేదీ సూచించబడతాయి.",
  "exports.createBusinessFirst": "ముందుగా ఒక వ్యాపారాన్ని సృష్టించండి — ఎగుమతులు ఒక వ్యాపారానికి చెందుతాయి, యాప్‌కు కాదు.",
  "exports.lockedTitle": "CSV మరియు Excel ఎగుమతులు అనేది Business ఫీచర్",
  "exports.lockedDesc": "మీ వర్క్‌స్పేస్ Essentials ప్లాన్‌లో ఉంది. Business, CSV మరియు Excel ఎగుమతులు, స్టాక్ విలువ నిర్ధారణ, అపరిమిత ఉత్పత్తులు మరియు సిబ్బంది, సరఫరాదారులు, కొనుగోలు మరియు బండిల్‌లను జోడిస్తుంది.",
  "exports.seeBusiness": "Business లో ఏమి ఉంటుందో చూడండి",
  "exports.whatTheseAre": "ఈ ఫైల్‌లు ఏమిటి",
  "exports.about1": "ప్రతి డేటాసెట్ CSV గా లేదా నిజమైన Excel వర్క్‌బుక్ (.xlsx) గా వస్తుంది — పూర్తి ఇన్వెంటరీ వర్క్‌బుక్ Excel-మాత్రమే, ప్రతి డేటాసెట్‌కు ఒక షీట్ ఉంటుంది. CSV ఫైల్‌లు Excel, Numbers, Google Sheets మరియు చాలా స్టాక్ యాప్‌లలో తెరుచుకుంటాయి. UTF-8 టెక్స్ట్, కోట్ చేసిన కామాలు, గమనికలలోని లైన్ బ్రేక్‌లు మరియు కోడ్‌లలోని ముందస్తు సున్నాలు అన్నీ భద్రపరచబడతాయి, మరియు ఫార్ములా లాగా ప్రారంభమయ్యే సెల్‌లు స్ప్రెడ్‌షీట్ వాటిని టెక్స్ట్‌గా తెరిచే విధంగా తటస్థీకరించబడతాయి.",
  "exports.about2": "Excel ఫైల్‌లలో, SKU లు, UPC లు, ISBN లు మరియు బార్‌కోడ్‌లు టెక్స్ట్ సెల్‌లు — ఎప్పుడూ శాస్త్రీయ సంజ్ఞామానం కాదు మరియు ఎప్పుడూ తగ్గించిన సున్నాలు కాదు — నిలువు వరుస వెడల్పులు, హెడర్ ఫిల్టర్‌లు మరియు కరెన్సీ లేదా పరిమాణ ఫార్మాట్‌లు వర్తింపజేయబడతాయి. పూర్తి ఇన్వెంటరీ వర్క్‌బుక్ ఉత్పత్తులు, స్టాక్ స్థాయిలు, స్థానాలు మరియు కదలికలను వేర్వేరు షీట్‌లలో ఉంచుతుంది.",
  "exports.about3": "చాలా పెద్ద ఎగుమతులు ప్రతి డేటాసెట్‌కు 20,000 వరుసల వద్ద ఆగుతాయి — అది జరిగినప్పుడు ఫైల్ పేరు దానిని సూచిస్తుంది (truncated-20000), కాబట్టి పాక్షిక ఫైల్ ఎప్పుడూ పూర్తి ఫైల్‌గా పరిగణించబడదు.",
  "exports.about4": "బ్యాకప్ అనేది మీ డేటా యొక్క స్నాప్‌షాట్, ఒకే క్లిక్‌తో పునరుద్ధరణ కాదు. దానిని పునరుద్ధరించడం అనేది మాన్యువల్, ముందుగా సమీక్షించే పని, కాబట్టి ఫైల్‌ను సురక్షితంగా ఉంచండి — తొలగించిన వ్యాపారాన్ని దాని నుండి యాప్‌లో ఇంకా ఏదీ తిరిగి సృష్టించలేదు. యాప్ కోడ్ మరియు Base44 ప్లాట్‌ఫారమ్ బ్యాకప్‌లు ఈ ఫైల్‌ల నుండి వేరుగా నిర్వహించబడతాయి.",
  "exports.about5": "ఫోటోలు మరియు జోడింపులు వాటి నిల్వ చేసిన లింక్‌లుగా జాబితా చేయబడతాయి — చిత్ర ఫైల్‌లే డౌన్‌లోడ్‌లో ప్యాక్ చేయబడవు.",
  "exports.backupTitle": "పూర్తి బ్యాకప్",
  "exports.backupDesc": "ఈ వ్యాపారం యొక్క ఉత్పత్తులు, స్థానాలు, స్టాక్ స్థాయిలు, పూర్తి కదలిక లెడ్జర్, సరఫరాదారులు, కొనుగోలు, ఆర్డర్‌లు, రిటర్న్‌లు, గణనలు మరియు లిస్టింగ్‌లతో పాటు దాని ప్రొఫైల్ సెట్టింగ్‌లతో ఒక ఫైల్. దానిని మీరు నియంత్రించే చోట ఉంచండి.",
