  "import.eyebrow": "డేటా",
  "import.title": "దిగుమతి కేంద్రం",
  "import.subtitleStart": "మూడు వేర్వేరు స్ప్రెడ్‌షీట్ కార్యకలాపాలు, కాబట్టి ధర సవరణ ఎప్పుడూ స్టాక్ రసీదుగా రాదు. ప్రతిదీ దీనిలో మాత్రమే చేరుతుంది",
