  "import.createBusinessFirst": "ముందుగా ఒక వ్యాపారాన్ని సృష్టించండి — దిగుమతి చేసిన ఉత్పత్తులు ఒక వ్యాపారానికి చెందుతాయి.",
  "import.createBusinessFirstShort": "ముందుగా ఒక వ్యాపారాన్ని సృష్టించండి.",
  "import.whatEachDoes": "ప్రతి కార్యకలాపం ఏమి చేస్తుంది",
  "import.createTitle": "కొత్త ఉత్పత్తులను సృష్టించండి",
  "import.createDesc": "ఇంకా కేటలాగ్‌లో లేని వరుసలను జోడిస్తుంది. ఇప్పటికే ఉపయోగంలో ఉన్న నకిలీ SKU లు మరియు బార్‌కోడ్‌లు దాటవేయబడతాయి, మరియు ప్రారంభ స్టాక్ మీరు ఎంచుకునే స్థానంలో రసీదుగా చేరవచ్చు.",
  "import.updateTitle": "ఉన్న ఉత్పత్తులను నవీకరించండి",
  "import.updateDesc": "ప్రతి వరుసను SKU లేదా రికార్డ్ ID ద్వారా సరిపోల్చుతుంది మరియు పాత విలువను ప్రతిపాదిత కొత్త విలువ పక్కన చూపుతుంది. ఖాళీ సెల్‌లు, ఖాళీలను తొలగించమని మీరు కోరితే తప్ప, సేవ్ చేసిన విలువను అలాగే ఉంచుతాయి, మరియు పరిమాణాలు ఎప్పుడూ తాకబడవు.",
  "import.receiveModeTitle": "స్టాక్ స్వీకరించండి",
  "import.receiveModeDesc": "వచ్చే పరిమాణాలను ఒక స్థానానికి జోడిస్తుంది మరియు ప్రతి లైన్‌కు కదలిక లెడ్జర్‌కు ఒక రసీదును వ్రాస్తుంది. ప్రతి బ్యాచ్ గుర్తించబడుతుంది, కాబట్టి అదే షీట్‌ను రెండుసార్లు స్వీకరించలేరు.",
  "import.excelNote": "Excel వర్క్‌బుక్‌లు (.xlsx) నేరుగా చదవబడతాయి — వర్క్‌షీట్‌ను ఎంచుకోండి మరియు నిలువు వరుసలు మీ కోసం సరిపోల్చబడతాయి. కోడ్‌లు పూర్తిగా ఉంటాయి: టెక్స్ట్‌గా సేవ్ చేసిన UPC దాని అంకెలు మరియు ముందస్తు సున్నాలను ఉంచుతుంది. దిగుమతి చేయలేని వరుసలు ఒక కారణంతో జాబితా చేయబడతాయి",
