  "reports.footnote": "అమ్మకాలు ప్రతి ఉత్పత్తి యొక్క ప్రస్తుత రిటైల్ ధరను ఉపయోగిస్తాయి, రసీదులు స్టాక్ వచ్చినప్పుడు నమోదు చేసిన ఖర్చును ఉపయోగిస్తాయి, మరియు నష్టాలు ప్రస్తుత యూనిట్ ఖర్చును ఉపయోగిస్తాయి. తప్పిపోయిన డబ్బు ఎప్పుడూ సున్నాగా పరిగణించబడదు — అది తెలిసే వరకు ఒక సంఖ్యను ఖాళీగా ఉంచండి. నివేదిక అనేది ఒక వీక్షణ, పత్రం కాదు: మీరు ఒకదాన్ని నిర్వహించినప్పుడు మీ రికార్డులకు ఏదీ వ్రాయబడదు.",
