  "payroll.dd.help": "ప్రతి బృంద సభ్యుని బ్యాంక్ వివరాలను సురక్షితంగా సేకరించండి. సమర్పించిన వివరాలు యజమానికి మాత్రమే వెళ్తాయి - వాటిని మరెవరూ చూడలేరు.",
