  "payroll.dd.savings": "Savings",
  "payroll.dd.steps.body": "1. ACH చెల్లింపులు పంపగల వ్యాపార బ్యాంక్ ఖాతా మీకు అవసరం. 2. ప్రతి బృంద సభ్యుని నుండి సంతకం చేసిన అధికార ఫారమ్‌ను సేకరించండి - రద్దు చేసిన చెక్ నంబర్‌లను ధృవీకరించడానికి సహాయపడుతుంది. 3. డబ్బు సమయానికి చేరేలా వేతన దినానికి 2-3 వ్యాపార దినాల ముందు పేరోల్‌ను పంపండి. 4. చాలా రాష్ట్రాలకు బృంద సభ్యుని వ్రాతపూర్వక సమ్మతి అవసరం. ఈ యాప్ ఫారమ్‌లను సేకరిస్తుంది మరియు దశల ద్వారా మిమ్మల్ని నడిపిస్తుంది - డబ్బును నిజంగా పంపడం మీ స్వంత బ్యాంక్ ద్వారా జరుగుతుంది.",
  "payroll.dd.steps.title": "డైరెక్ట్ డిపాజిట్ ఎలా పనిచేస్తుంది",
