  "training.newForYou": "మీ కోసం కొత్త శిక్షణ",
  "training.newForYouHelp": "మీ పాత్ర పెరగడం వల్ల, లేదా ఎవరైనా వాటిని మీకు కేటాయించడం వల్ల ఈ పాఠాలు జోడించబడ్డాయి. యాప్ కొత్త భాగాలను నేర్చుకోవడానికి వాటిని పూర్తి చేయండి.",
