  "recovery.emailMeCodeHint": "మీరు బ్యాకప్ ఇమెయిల్‌ను సెటప్ చేసి ఉంటే, మేము అక్కడికి 6-అంకెల కోడ్‌ను పంపుతాం. మీ ఖాతాను రక్షించడానికి, కోడ్ పంపబడినా లేకపోయినా ఈ పేజీ ఎల్లప్పుడూ అదే విధంగా సమాధానం ఇస్తుంది.",
