  "settings.security.backupCodesDesc": "ఒక-సారి విడి కీలు. వాటిని ముద్రించండి లేదా రాసి సురక్షితమైన చోట ఉంచండి — మీరు మీ ఇమెయిల్‌ను కోల్పోతే ప్రతి ఒక్కటి మిమ్మల్ని ఒక్కసారి తిరిగి తీసుకురాగలదు.",
