  "settings.security.generateCodes": "బ్యాకప్ కోడ్‌లను ఉత్పత్తి చేయండి",
  "settings.security.regenerateCodes": "కొత్త సెట్‌ను ఉత్పత్తి చేయండి",
  "settings.security.newCodesTitle": "మీ కొత్త బ్యాకప్ కోడ్‌లు",
  "settings.security.codesOnceWarning": "ఈ కోడ్‌లు ఒక్కసారి మాత్రమే చూపబడతాయి — మేము గజిబిజి కాపీని మాత్రమే ఉంచుతాం, కాబట్టి మేము కూడా వాటిని మళ్లీ చూపలేము. కొత్త సెట్‌ను ఉత్పత్తి చేయడం పాత కోడ్‌లన్నిటినీ రద్దు చేస్తుంది.",
  "settings.security.printCodes": "ఈ కోడ్‌లను ముద్రించండి",
  "settings.security.backupEmailTitle": "బ్యాకప్ ఇమెయిల్",
  "settings.security.backupEmailDesc": "మీరు నియంత్రించే రెండవ ఇమెయిల్ చిరునామా. మీ ప్రధాన ఇమెయిల్ ఎప్పుడైనా అందుబాటులో లేకపోతే, బదులుగా ఇక్కడికి పునరుద్ధరణ కోడ్‌ను పంపవచ్చు.",
