  "rewards.give.help": "బహుమతులు ఒక బృంద సభ్యుడికి వెళ్తాయి. మేనేజర్‌లు సిబ్బందికి బహుమతి ఇస్తారు; యజమాని బృందంలో ఎవరికైనా బహుమతి ఇవ్వగలరు.",
